// Lấy input gốc từ Init Meta
const meta = $items('Init Meta')[0].json;

// Helper đếm số item từ mỗi nhánh Append
function countItems(nodeName) {
  try {
    return $items(nodeName).length || 0;
  } catch (e) {
    return 0;
  }
}

return [{
  keyword: meta.keyword,
  limit: meta.limit,
  platforms: meta.platforms,
  batch_id: meta.batch_id,
  extract_time: meta.extract_time,
  campaign_name: meta.campaign_name,
  source: meta.source,
  sheet_document: 'Ultimate Extract | by RoboNuggets (R46)',
  summary: {
    meta_ads:      countItems('Append row Meta Ads'), // sửa tên node theo thực tế
    tiktok:        countItems('Append row TikTok'),
    instagram:     countItems('Append row Instagram'),
    youtube_longs: countItems('Append row YouTube Longs'),
    youtube_shorts:countItems('Append row YouTube Shorts'), // nếu khác thì đổi lại
    linkedin:      countItems('Append row LinkedIn'),
    x_twitter:     countItems('Append row Twitter'),
    reddit:        countItems('Append row Reddit'),
  },
}];

const meta = $json;
const items = meta.items || [];
const count = meta.count || 0;

// Summarize for AI Reasoning
let markdown = `## MARKET RESEARCH: ${meta.keyword}
Total items scraped: ${count}

`;

// Group by platform
let platforms = {};
items.forEach(i => {
  if (!platforms[i.platform]) platforms[i.platform] = [];
  platforms[i.platform].push(i);
});

for (const [plat, platsItems] of Object.entries(platforms)) {
  markdown += `### Top Ads on ${plat.toUpperCase()}
`;
  // Only take top 3 per platform to avoid token overflow
  const top = platsItems.slice(0, 3);
  top.forEach(i => {
    markdown += `- **Caption**: ${i.caption.substring(0, 150)}...
`;
    markdown += `  - Stats: ${i.likes} likes, ${i.comments} comments, ${i.shares} shares
`;
    markdown += `  - Link: ${i.url}
`;
  });
  markdown += `
`;
}

return [{
  json: {
    market_research_summary: markdown,
    raw_count: count
  }
}];

// Lấy meta
const meta = $items('Init Meta')[0].json;

// Lấy danh sách từ từng node
function collect(sheetNode, altNode, platformName) {
  let items = [];
  try {
    // Thử lấy từ Sheet Appender trước
    items = $items(sheetNode);
    if (!items || items.length === 0) throw new Error("empty");
  } catch (e) {
    // Nếu Sheet Appender bị vô hiệu hóa (Bypass), lấy từ Edit Fields
    try {
      items = $items(altNode);
    } catch(err) {
      items = [];
    }
  }

  return items.map((item, idx) => ({
    index: idx + 1,
    platform: platformName,
    caption: item.json.caption || item.json.title || "",
    date_posted: item.json.date_posted || "",
    username: item.json.username || "",
    url: item.json.tiktok_url 
          || item.json.instagram_url
          || item.json.youtube_url
          || item.json.linkedin_url
          || item.json.x_url
          || item.json.reddit_url
          || "",
    likes: item.json.likes || item.json.upvotes || 0,
    shares: item.json.shares || 0,
    views: item.json.views || "",
    comments: item.json.comments || 0,
    bookmarks: item.json.bookmarks || 0
  }));
}

const list = [
  ...collect("Append row Meta Ads", "Edit Fields3", "meta"),
  ...collect("Append row TikTok", "Edit Fields", "tiktok"),
  ...collect("Append row Instagram", "Edit Fields4", "instagram"),
  ...collect("Append row YouTube Longs", "Edit Fields1", "youtube"),
  ...collect("Append row YouTube Shorts", "Edit Fields2", "youtube shorts"),
  ...collect("Append row LinkedIn", "Edit Fields5", "linkedin"),
  ...collect("Append row Twitter", "Edit Fields6", "twitter"),
  ...collect("Append row Reddit", "Edit Fields7", "reddit"),
];

// Trả về toàn bộ dữ liệu
return [{
  json: {
    keyword: meta.keyword,
    limit: meta.limit,
    items: list,
    count: list.length
  }
}];
